  favicon: '/favicon.svg',

  // ── Behavior ──
  layout: 'modern',              // 'modern' | 'classic'
  darkMode: true,
  forceDarkModeState: 'dark',    // 'dark' | 'light'
  hideDarkModeToggle: false,
  hideModels: false,
  hideSearch: false,
